-- 세트 343: 도커 헬스체크와 재시작 정책 실습: --health-cmd, State.Health, health 필터, HEALTHCHECK, --restart, RestartCount, update
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_docker_health_restart_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (343, 1, '헬스체크를 달아 컨테이너 띄우기', '컨테이너 `app` 을 백그라운드로 띄우되, **2초마다** `test -f /tmp/ok` 를 실행해 건강 상태를 보고 **1번만 실패해도** unhealthy 로 판정하게 하세요. (`alpine` 이미지에서 `sleep 300` 을 실행)', '`docker run` 에는 이름이 `--health-` 로 시작하는 옵션이 여럿 있어요. 검사 명령, 검사 간격, 실패 허용 횟수를 각각 정합니다. 간격은 `2s` 처럼 단위를 붙여요.', 'docker run -d --name app --health-cmd ''test -f /tmp/ok'' --health-interval 2s --health-retries 1 alpine sleep 300
docker inspect -f ''{{.State.Health.Status}}'' app

# /tmp/ok 가 아직 없으니 잠시 starting 이었다가 unhealthy 가 된다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.State.Running}}'' app)\\" = true ] ) && ( docker inspect -f ''{{json .Config.Healthcheck.Test}}'' app | grep -q ''test -f /tmp/ok'' ) && ( [ \\"$(docker inspect -f ''{{.Config.Healthcheck.Interval}}'' app)\\" = 2s ] ) && ( [ \\"$(docker inspect -f ''{{.Config.Healthcheck.Retries}}'' app)\\" = 1 ] ) && ( for i in $(seq 1 12); do [ \\"$(docker inspect -f ''{{.State.Health.Status}}'' app)\\" = unhealthy ] && exit 0; sleep 2; done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "app 이 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' app)\\" = true ]"]}, {"label": "검사 명령이 test -f /tmp/ok 다", "cmd": ["sh", "-c", "docker inspect -f ''{{json .Config.Healthcheck.Test}}'' app | grep -q ''test -f /tmp/ok''"]}, {"label": "검사 간격이 2초다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.Config.Healthcheck.Interval}}'' app)\\" = 2s ]"]}, {"label": "실패 허용 횟수가 1 이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.Config.Healthcheck.Retries}}'' app)\\" = 1 ]"]}, {"label": "파일이 없어 결국 unhealthy 가 된다", "cmd": ["sh", "-c", "for i in $(seq 1 12); do [ \\"$(docker inspect -f ''{{.State.Health.Status}}'' app)\\" = unhealthy ] && exit 0; sleep 2; done; exit 1"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (343, 2, '헬스 상태를 읽는 템플릿', '컨테이너 `app` 의 건강 상태(`starting`, `healthy`, `unhealthy` 중 하나)만 출력하는 `docker inspect` 템플릿의 빈칸을 채우세요.', '건강 상태는 `State` 아래 헬스체크 전용 묶음 안의 `Status` 에 들어 있어요. 컨테이너 자체의 실행 상태(running, exited)와는 다른 항목입니다.', NULL, NULL, '[]', 'fill', '["Health", "Healthy", "Running", "Probe"]', NULL, '건강 상태는 `.State.Health.Status` 에 있고 값은 `starting`(아직 판정 전), `healthy`, `unhealthy` 입니다. 실행 상태는 `.State.Status`(running, exited 등)로 따로 있어서 둘은 다른 질문이에요. 헬스체크를 설정하지 않은 컨테이너에는 `.State.Health` 자체가 없습니다.', '[0]', 'docker inspect -f ''{{.State.{0}.Status}}'' app', NULL, '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (343, 3, 'unhealthy 컨테이너를 healthy 로 만들기', '컨테이너 `svc` 는 2초마다 `/tmp/ok` 파일이 있는지 검사하는데, 파일이 없어서 unhealthy 입니다. **컨테이너를 다시 만들지 말고** 건강 상태가 `healthy` 가 되게 하세요.', '검사가 보는 것은 컨테이너 **안쪽**의 `/tmp/ok` 예요. 실행 중인 컨테이너 안에서 명령을 실행하는 `docker exec` 로 파일을 만들면 다음 검사 때 통과합니다.', 'docker exec svc touch /tmp/ok
# 2초 안팎으로 다음 검사가 돌고 나면 healthy
docker inspect -f ''{{.State.Health.Status}}'' svc

# 파일을 지우면 다시 unhealthy 가 된다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name svc --health-cmd ''test -f /tmp/ok'' --health-interval 2s --health-retries 1 alpine sleep 600 >/dev/null; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.State.Running}}'' svc)\\" = true ] ) && ( for i in $(seq 1 12); do [ \\"$(docker inspect -f ''{{.State.Health.Status}}'' svc)\\" = healthy ] && exit 0; sleep 2; done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "svc 가 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' svc)\\" = true ]"]}, {"label": "건강 상태가 healthy 다", "cmd": ["sh", "-c", "for i in $(seq 1 12); do [ \\"$(docker inspect -f ''{{.State.Health.Status}}'' svc)\\" = healthy ] && exit 0; sleep 2; done; exit 1"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (343, 4, 'unhealthy 컨테이너 이름만 모으기', '컨테이너 세 개(`ok1`, `bad1`, `bad2`)가 떠 있고 그중 일부가 unhealthy 입니다. **unhealthy 인 컨테이너의 이름만** `/tmp/work/bad.txt` 에 저장하세요. (한 줄에 하나, 눈으로 읽어 적지 말고 도커에게 걸러 달라고 하세요)', '`docker ps` 에는 건강 상태로 거르는 `--filter` 값이 있어요. 출력 모양은 `--format` 으로 이름만 나오게 줄일 수 있습니다. 결과를 `>` 로 파일에 넘기세요.', 'docker ps --filter health=unhealthy --format ''{{.Names}}'' > /tmp/work/bad.txt
cat /tmp/work/bad.txt

# health=healthy, health=starting 으로도 거를 수 있다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; for n in ok1 bad1 bad2; do docker run -d --name $n --health-cmd ''test -f /tmp/ok'' --health-interval 2s --health-retries 1 alpine sleep 600 >/dev/null; done; docker exec ok1 touch /tmp/ok; for i in $(seq 1 15); do [ \\"$(docker ps -q --filter health=unhealthy | wc -l)\\" -ge 2 ] && break; sleep 2; done; true"]', '["sh", "-c", "( [ -f /tmp/work/bad.txt ] && [ \\"$(tr -d '' '' < /tmp/work/bad.txt | sort | tr ''\\\\n'' '' '')\\" = \\"bad1 bad2 \\" ] ) && ( for i in $(seq 1 12); do [ \\"$(docker inspect -f ''{{.State.Health.Status}}'' ok1)\\" = healthy ] && exit 0; sleep 2; done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일에 unhealthy 둘만 들어 있다", "cmd": ["sh", "-c", "[ -f /tmp/work/bad.txt ] && [ \\"$(tr -d '' '' < /tmp/work/bad.txt | sort | tr ''\\\\n'' '' '')\\" = \\"bad1 bad2 \\" ]"]}, {"label": "ok1 은 여전히 healthy 다", "cmd": ["sh", "-c", "for i in $(seq 1 12); do [ \\"$(docker inspect -f ''{{.State.Health.Status}}'' ok1)\\" = healthy ] && exit 0; sleep 2; done; exit 1"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (343, 5, 'Dockerfile 에 HEALTHCHECK 넣기', '`/tmp/work/Dockerfile` 에는 `alpine` 에서 `sleep 300` 만 하는 이미지가 적혀 있습니다. 여기에 **2초 간격, 실패 1회 허용**으로 `test -f /tmp/ok` 를 검사하는 `HEALTHCHECK` 를 넣어 `/tmp/work` 에서 이미지 `hc:1` 을 빌드하고, 그 이미지로 컨테이너 `built` 를 띄우세요.', '`HEALTHCHECK` 지시어는 `--interval=`, `--retries=` 같은 옵션을 앞에 붙이고, 그 뒤에 `CMD` 와 검사 명령을 적어요. 이미지 이름과 태그는 `docker build` 의 `-t` 로 정합니다.', 'cd /tmp/work
printf ''FROM alpine\\nHEALTHCHECK --interval=2s --retries=1 CMD test -f /tmp/ok\\nCMD ["sleep","300"]\\n'' > Dockerfile
docker build -t hc:1 .
docker run -d --name built hc:1
docker inspect -f ''{{.State.Health.Status}}'' built

# docker run 의 --health-* 옵션은 이미지의 HEALTHCHECK 를 덮어쓴다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; printf ''FROM alpine\\\\nCMD [\\"sleep\\",\\"300\\"]\\\\n'' > /tmp/work/Dockerfile; true"]', '["sh", "-c", "( docker image inspect -f ''{{json .Config.Healthcheck.Test}}'' hc:1 | grep -q ''test -f /tmp/ok'' ) && ( [ \\"$(docker image inspect -f ''{{.Config.Healthcheck.Interval}}'' hc:1)\\" = 2s ] ) && ( [ \\"$(docker inspect -f ''{{.State.Running}}'' built)\\" = true ] && [ \\"$(docker inspect -f ''{{.Config.Image}}'' built)\\" = hc:1 ] ) && ( for i in $(seq 1 12); do docker inspect -f ''{{.State.Health.Status}}'' built | grep -Eq ''^(starting|healthy|unhealthy)$'' && exit 0; sleep 2; done; exit 1 ) && ( grep -q ''^HEALTHCHECK'' /tmp/work/Dockerfile )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지에 검사 명령이 들어 있다", "cmd": ["sh", "-c", "docker image inspect -f ''{{json .Config.Healthcheck.Test}}'' hc:1 | grep -q ''test -f /tmp/ok''"]}, {"label": "이미지의 검사 간격이 2초다", "cmd": ["sh", "-c", "[ \\"$(docker image inspect -f ''{{.Config.Healthcheck.Interval}}'' hc:1)\\" = 2s ]"]}, {"label": "built 가 hc:1 로 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' built)\\" = true ] && [ \\"$(docker inspect -f ''{{.Config.Image}}'' built)\\" = hc:1 ]"]}, {"label": "built 에 건강 상태가 붙는다", "cmd": ["sh", "-c", "for i in $(seq 1 12); do docker inspect -f ''{{.State.Health.Status}}'' built | grep -Eq ''^(starting|healthy|unhealthy)$'' && exit 0; sleep 2; done; exit 1"]}, {"label": "Dockerfile 에 HEALTHCHECK 가 있다", "cmd": ["sh", "-c", "grep -q ''^HEALTHCHECK'' /tmp/work/Dockerfile"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (343, 6, 'unhealthy 가 되면 도커는 무엇을 할까', '재시작 정책 없이 헬스체크만 붙인 컨테이너가 검사에 계속 실패해 `unhealthy` 가 되었습니다. 도커 엔진은 어떻게 할까요?', '`docker ps` 의 STATUS 열을 떠올려 보세요. 헬스체크가 하는 일은 "판정해서 표시"까지예요. 그 표시를 보고 무언가를 하는 건 또 다른 장치의 몫입니다.', NULL, NULL, '[]', 'choice', '["엔진이 컨테이너를 자동으로 한 번 재시작해서 복구를 시도한다", "상태 표시만 unhealthy 로 바뀌고 컨테이너는 계속 실행된다", "컨테이너가 곧바로 종료되어 Exited 상태로 바뀐다", "컨테이너가 삭제되어 docker ps -a 에서도 사라진다"]', 1, '헬스체크는 **판정하고 기록**할 뿐이라 일반 `docker run` 컨테이너는 unhealthy 여도 계속 실행됩니다. 재시작은 `--restart` 정책이 **프로세스 종료**를 보고 하는 일이고, 정책은 unhealthy 만으로는 동작하지 않아요. (Swarm 같은 오케스트레이터는 unhealthy 태스크를 교체하기도 하지만, 단독 도커 엔진은 아닙니다.)', NULL, NULL, NULL, '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (343, 7, '실패하면 최대 3번까지만 재시작', '컨테이너 `crash` 를 백그라운드로 띄우되 시작하자마자 종료 코드 1 로 죽게 하고(`alpine` 에서 `sh -c "exit 1"`), 도커가 **실패했을 때만, 최대 3번까지** 다시 시작하게 하세요.', '`docker run` 의 재시작 정책 옵션은 `정책이름:횟수` 모양으로 적어요. "종료 코드가 0 이 아닐 때" 를 뜻하는 정책 이름을 찾아보세요. 확인은 HostConfig 의 `RestartPolicy` 항목과 `RestartCount` 로 해요.', 'docker run -d --name crash --restart on-failure:3 alpine sh -c ''exit 1''
docker inspect -f ''{{.HostConfig.RestartPolicy.Name}} {{.HostConfig.RestartPolicy.MaximumRetryCount}} {{.RestartCount}}'' crash

# 3번 재시작해 본 뒤에는 포기하고 Exited 로 남는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.HostConfig.RestartPolicy.Name}}'' crash)\\" = on-failure ] ) && ( [ \\"$(docker inspect -f ''{{.HostConfig.RestartPolicy.MaximumRetryCount}}'' crash)\\" = 3 ] ) && ( for i in $(seq 1 15); do [ \\"$(docker inspect -f ''{{.RestartCount}}'' crash)\\" -ge 1 ] && exit 0; sleep 2; done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "정책 이름이 on-failure 다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.RestartPolicy.Name}}'' crash)\\" = on-failure ]"]}, {"label": "최대 재시도가 3 이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.RestartPolicy.MaximumRetryCount}}'' crash)\\" = 3 ]"]}, {"label": "실제로 재시작이 일어났다", "cmd": ["sh", "-c", "for i in $(seq 1 15); do [ \\"$(docker inspect -f ''{{.RestartCount}}'' crash)\\" -ge 1 ] && exit 0; sleep 2; done; exit 1"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (343, 8, '정상 종료해도 다시 시작하는 정책', '컨테이너 `keep` 을 `unless-stopped` 정책으로 백그라운드로 띄우세요. 안에서는 **3초 뒤에 오류 없이(종료 코드 0) 끝나는** 명령(`alpine` 에서 `sleep 3`)을 실행합니다. 도커가 스스로 다시 시작해서 재시작 횟수가 1 이상이 되어야 합니다.', '정책 이름 중에 "내가 직접 stop 하기 전까지는 계속 살린다" 는 뜻의 것이 있어요. `on-failure` 는 정상 종료(코드 0)는 다시 시작하지 않지만 이 정책은 달라요. 확인은 `RestartCount` 로 해요.', 'docker run -d --name keep --restart unless-stopped alpine sleep 3
sleep 6
docker inspect -f ''{{.RestartCount}}'' keep

# on-failure 였다면 코드 0 으로 끝난 뒤 다시 시작하지 않는다. unless-stopped 는 stop 하기 전까지 계속 되살린다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.HostConfig.RestartPolicy.Name}}'' keep)\\" = unless-stopped ] ) && ( for i in $(seq 1 12); do [ \\"$(docker inspect -f ''{{.RestartCount}}'' keep)\\" -ge 1 ] && exit 0; sleep 2; done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "정책이 unless-stopped 다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.RestartPolicy.Name}}'' keep)\\" = unless-stopped ]"]}, {"label": "한 번 이상 재시작됐다", "cmd": ["sh", "-c", "for i in $(seq 1 12); do [ \\"$(docker inspect -f ''{{.RestartCount}}'' keep)\\" -ge 1 ] && exit 0; sleep 2; done; exit 1"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (343, 9, '재시작 횟수를 읽어 저장하기', '컨테이너 `loopy` 는 `on-failure:3` 정책으로 계속 실패하다가 지금은 멈춰 있습니다. 도커가 **재시작한 횟수** 숫자만 `/tmp/work/count.txt` 에 저장하세요. (직접 세지 말고 도커에게 물어보세요)', '재시작 횟수는 컨테이너 상세 정보의 최상위 항목 `RestartCount` 에 있어요. `docker inspect -f` 로 그 항목만 뽑아 `>` 로 파일에 넘기세요.', 'docker inspect -f ''{{.RestartCount}}'' loopy > /tmp/work/count.txt
cat /tmp/work/count.txt

# 최대 재시도 3 에 도달하면 더는 늘지 않는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name loopy --restart on-failure:3 alpine sh -c ''exit 1'' >/dev/null; for i in $(seq 1 20); do [ \\"$(docker inspect -f ''{{.State.Status}}'' loopy)\\" = exited ] && break; sleep 2; done; true"]', '["sh", "-c", "( [ -f /tmp/work/count.txt ] && [ \\"$(cat /tmp/work/count.txt)\\" = \\"$(docker inspect -f ''{{.RestartCount}}'' loopy)\\" ] ) && ( [ \\"$(cat /tmp/work/count.txt)\\" -ge 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일에 현재 재시작 횟수가 들어 있다", "cmd": ["sh", "-c", "[ -f /tmp/work/count.txt ] && [ \\"$(cat /tmp/work/count.txt)\\" = \\"$(docker inspect -f ''{{.RestartCount}}'' loopy)\\" ]"]}, {"label": "횟수가 1 이상이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/work/count.txt)\\" -ge 1 ]"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (343, 10, 'always 컨테이너를 stop 하면', '컨테이너 `guard` 는 `--restart always` 로 실행 중입니다. 이 컨테이너를 **도커가 다시 살리지 않는 멈춘 상태**로 만드세요. (정책은 `always` 그대로 둡니다)', '`--restart always` 라도, 사용자가 직접 정지 명령을 내린 컨테이너는 도커가 되살리지 않아요. 컨테이너를 멈추는 가장 기본 명령을 쓰세요.', 'docker stop guard
sleep 3
docker inspect -f ''{{.State.Status}} {{.HostConfig.RestartPolicy.Name}}'' guard

# 데몬(도커 서비스) 자체가 재시작되면 always 는 다시 띄우지만, unless-stopped 는 띄우지 않는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name guard --restart always alpine sleep 600 >/dev/null; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.HostConfig.RestartPolicy.Name}}'' guard)\\" = always ] ) && ( [ \\"$(docker inspect -f ''{{.State.Running}}'' guard)\\" = false ] ) && ( sleep 4; [ \\"$(docker inspect -f ''{{.State.Running}}'' guard)\\" = false ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "정책은 그대로 always 다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.RestartPolicy.Name}}'' guard)\\" = always ]"]}, {"label": "멈춰 있다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' guard)\\" = false ]"]}, {"label": "잠시 뒤에도 되살아나지 않는다", "cmd": ["sh", "-c", "sleep 4; [ \\"$(docker inspect -f ''{{.State.Running}}'' guard)\\" = false ]"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (343, 11, '돌고 있는 컨테이너의 재시작 정책 바꾸기', '컨테이너 `worker` 는 재시작 정책 없이(`no`) 떠 있습니다. **컨테이너를 지우거나 다시 만들지 말고**, 정책을 `unless-stopped` 로 바꾸세요. 계속 실행 중이어야 합니다.', '이미 만들어진 컨테이너의 설정 일부를 고치는 `docker update` 가 있어요. 재시작 정책 옵션 이름은 `docker run` 에서와 같습니다.', 'docker update --restart unless-stopped worker
docker inspect -f ''{{.HostConfig.RestartPolicy.Name}}'' worker

# 같은 컨테이너(ID 그대로)에 설정만 바뀐다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name worker --restart no alpine sleep 600 >/dev/null; docker inspect -f ''{{.Id}}'' worker > /tmp/work/id.txt; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.HostConfig.RestartPolicy.Name}}'' worker)\\" = unless-stopped ] ) && ( [ \\"$(docker inspect -f ''{{.Id}}'' worker)\\" = \\"$(cat /tmp/work/id.txt)\\" ] ) && ( [ \\"$(docker inspect -f ''{{.State.Running}}'' worker)\\" = true ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "정책이 unless-stopped 다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.RestartPolicy.Name}}'' worker)\\" = unless-stopped ]"]}, {"label": "같은 컨테이너다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.Id}}'' worker)\\" = \\"$(cat /tmp/work/id.txt)\\" ]"]}, {"label": "실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' worker)\\" = true ]"]}]', '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (343, 12, '헬스체크와 재시작 정책을 점검하는 흐름', '헬스체크를 단 컨테이너를 띄워 상태를 확인하고, 고치고, 재시작 정책까지 정하는 흐름을 **앞에서 뒤**로 놓으세요.', '먼저 헬스체크를 달아 띄우고 → 상태를 읽고 → 원인을 고친 뒤 → 건강해졌는지 거르고 → 마지막으로 재시작 정책을 정하는 순서입니다.', NULL, NULL, '[]', 'order', '["`docker run -d --health-cmd ... --health-interval 2s` 로 헬스체크를 달아 컨테이너를 띄운다", "`docker inspect -f ''{{.State.Health.Status}}''` 로 starting → unhealthy 상태를 읽는다", "`docker exec` 로 검사가 보는 파일을 만들어 원인을 고친다", "`docker ps --filter health=healthy` 로 healthy 가 된 것을 확인한다", "`docker update --restart unless-stopped` 로 죽었을 때의 재시작 정책을 정한다"]', NULL, '**run(헬스체크) → inspect(상태 읽기) → exec(원인 고침) → ps --filter(확인) → update --restart(정책)** 순서입니다. 헬스체크는 상태를 알려 줄 뿐이고, 프로세스가 죽었을 때 살리는 일은 재시작 정책이 따로 맡아요.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "Docker 공식 문서: Dockerfile reference (HEALTHCHECK)", "url": "https://docs.docker.com/reference/dockerfile/"}, {"title": "Docker 공식 문서: Start containers automatically (재시작 정책)", "url": "https://docs.docker.com/engine/containers/start-containers-automatically/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: docker container ls (--filter)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]');
